export class QuoteService {
  async processQuote(quoteId: string, action: string, userId: string) {
    const quote = await this.repo.findById(quoteId);
    if (action === 'approve') {
      if (quote.tier === 'ENTERPRISE' && quote.total > 50000) {
        // needs manager approval first
        quote.status = 'PENDING_MANAGER';
        await this.notify(userId, 'manager_needed');
      } else {
        quote.status = 'APPROVED';
      }
    } else if (action === 'reject') {
      quote.status = 'REJECTED';
    } else if (action === 'expire') {
      quote.status = 'EXPIRED';
    }
    await this.repo.save(quote);
  }
}
